begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values('11111111-1111-4111-8111-111111111111','solver@example.invalid',now()),('33333333-3333-4333-8333-333333333333','abid.ibn.ashraf@gmail.com',now());
insert into public.profiles(id,username) values('11111111-1111-4111-8111-111111111111','Solver'),('33333333-3333-4333-8333-333333333333','Owner');
create temp table fixtures(name text primary key,code text,result jsonb);grant all on fixtures to authenticated;
create function pg_temp.link(label text,flags jsonb,trusted boolean default true) returns text language plpgsql as $$
declare payload jsonb;hash text;code text;
begin
 payload:=jsonb_build_object('format','fto-replay-v1','size',3,'complete',true,'solveMs',100,'duration',100,'usedPause',false,'initial',jsonb_build_object('case',label,'keyboard',jsonb_build_object('modes','[]'::jsonb)),'solver',jsonb_build_object('id','11111111-1111-4111-8111-111111111111','username','Solver'),'events','[]'::jsonb)||flags;
 hash:=public.store_recording(payload,trusted);code:=left(hash,32);insert into public.short_links(id,recording_hash,user_id) values(code,hash,'11111111-1111-4111-8111-111111111111');return code;
end;$$;
insert into fixtures(name,code) values('clean',pg_temp.link('clean','{}')),('undo',pg_temp.link('undo','{"usedUndo":true}')),('pause',pg_temp.link('pause','{"usedPause":true}')),('legacy-pause',pg_temp.link('legacy-pause','{"events":[{"type":"pause"}]}')),('unverified',pg_temp.link('unverified','{}',false)),('rejected',pg_temp.link('rejected','{}')),('changed',pg_temp.link('changed','{}')),('identity',pg_temp.link('identity','{"solver":{"id":"33333333-3333-4333-8333-333333333333","username":"Owner"}}',false));
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select throws_ok($$select public.inspect_leaderboard_recovery((select code from fixtures where name='clean'))$$,'P0001','Administrator access required','Solvers cannot inspect private recovery evidence');
select throws_ok($$select public.recover_leaderboard_single((select code from fixtures where name='clean'),'Bug recovery',true,true)$$,'P0001','Administrator access required','Solvers cannot add themselves to the leaderboard');
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select is((public.inspect_leaderboard_recovery((select code from fixtures where name='clean'))->>'username'),'Solver','Recovery identifies the recorded solver');
select is((public.inspect_leaderboard_recovery((select code from fixtures where name='clean'))->>'can_recover')::boolean,true,'A clean recording can be recovered');
select throws_ok($$select public.recover_leaderboard_single((select code from fixtures where name='clean'),'Bug recovery',false,true)$$,'P0001','Review the replay and keyboard layout before adding this solve','A preview cannot accidentally approve a result');
select throws_ok($$select public.recover_leaderboard_single((select code from fixtures where name='clean'),'x',true,true)$$,'P0001','Explain the recovery in 3–500 characters','Recovery requires a reason');
update fixtures set result=public.recover_leaderboard_single(code,'Submission was blocked by a verified bug',true,true) where name='clean';
select is((select result->>'status' from fixtures where name='clean'),'approved','Explicit admin confirmation approves a recovered solve');
select is(public.inspect_leaderboard_recovery((select result->>'id' from fixtures where name='clean'))->>'username','Solver','Recovery also accepts a single submission ID');
select is((public.recover_leaderboard_single((select code from fixtures where name='clean'),'Same recording retry',true,true)->>'already_added')::boolean,true,'Repeated recovery reuses the approved result');
set local role postgres;
select is((select count(*)::int from public.submission_notifications),1,'Repeated recovery sends one approval notification');
select is((select count(*)::int from public.attempts),0,'Manual recovery does not fabricate an online attempt');
select is((select count(*)::int from public.recording_objects),(select count(*)::int from fixtures),'Recovery reuses the existing recording payload');
set local role authenticated;
select is((public.inspect_leaderboard_recovery((select code from fixtures where name='undo'))->>'can_recover')::boolean,false,'Undo is a blocking recovery flag');
select is((public.inspect_leaderboard_recovery((select code from fixtures where name='pause'))->>'can_recover')::boolean,false,'Pause is a blocking recovery flag');
select is((public.inspect_leaderboard_recovery((select code from fixtures where name='legacy-pause'))->>'can_recover')::boolean,false,'Legacy pause events are detected');
select throws_ok($$select public.recover_leaderboard_single((select code from fixtures where name='pause'),'Ignore pause',true,true)$$,'P0001','This recording has disqualifying evidence and cannot be added','Acknowledging warnings cannot override pause disqualification');
select throws_ok($$select public.recover_leaderboard_single((select code from fixtures where name='unverified'),'Missing online evidence',true,false)$$,'P0001','Acknowledge the recording warnings before adding this solve','Unverified recordings need explicit warning acknowledgement');
select throws_ok($$select public.recover_leaderboard_single((select code from fixtures where name='undo'),'Ignore undo',true,true)$$,'P0001','This recording has disqualifying evidence and cannot be added','Undo cannot be overridden by a forged confirmation');
select is((public.inspect_leaderboard_recovery((select code from fixtures where name='identity'))->>'can_recover')::boolean,false,'Unverified solver attribution mismatch blocks recovery');
select lives_ok($$select public.recover_leaderboard_single((select code from fixtures where name='unverified'),'Independently verified solver and recording',true,true)$$,'Admin may recover missing online evidence after explicit manual verification');
set local role postgres;
insert into public.submissions(user_id,metric,ms,status,evidence_refs) select '11111111-1111-4111-8111-111111111111','single',100,'pending',jsonb_build_array(jsonb_build_object('ms',100,'dnf',false,'recording_hash',l.recording_hash)) from public.short_links l where l.id=(select code from fixtures where name='rejected');
select public.review_submission((select id from public.submissions where status='pending'),false,'Rejected before bug was identified');
update fixtures set result=public.recover_leaderboard_single(code,'Rechecked after the submission bug was fixed',true,true) where name='rejected';
select is((select count(*)::int from public.submissions where status='rejected'),1,'Recovery preserves the original rejection history');
select is((select count(*)::int from public.submission_notifications where decision='rejected'),1,'The original rejection notification is preserved');
select is((select count(*)::int from public.submission_notifications where decision='approved'),3,'Recovery of a rejected solve creates a new approval without notification conflicts');
select is((select count(*)::int from public.submissions where recovery_source is not null),3,'Recovery source and admin review remain auditable');
select public.inspect_leaderboard_recovery((select code from fixtures where name='changed'));
update public.recording_objects set payload=jsonb_set(payload,'{usedPause}','true') where hash=(select recording_hash from public.short_links where id=(select code from fixtures where name='changed'));
select throws_ok($$select public.recover_leaderboard_single((select code from fixtures where name='changed'),'Stale clean preview',true,true)$$,'P0001','This recording has disqualifying evidence and cannot be added','Recovery rechecks flags on the server instead of trusting a stale preview');
insert into fixtures(name,code) values('draft',pg_temp.link('draft','{}'));
insert into public.submissions(user_id,metric,ms,status,evidence_refs) select '11111111-1111-4111-8111-111111111111','single',150,'draft',jsonb_build_array(jsonb_build_object('ms',150,'dnf',false,'recording_hash',l.recording_hash)) from public.short_links l where l.id=(select code from fixtures where name='draft');
update fixtures set result=jsonb_build_object('original_id',(select id from public.submissions where status='draft')) where name='draft';
select is(public.recover_leaderboard_single((select code from fixtures where name='draft'),'Rechecked the original recording time',true,true)->>'id',(select result->>'original_id' from fixtures where name='draft'),'A matching unreviewed draft is reused rather than duplicated');
select is((select ms from public.submissions where id=(select (result->>'original_id')::uuid from fixtures where name='draft')),100::double precision,'Recovery derives the final time from the recording rather than stale draft metadata');
set local role anon;
select throws_ok($$select public.inspect_leaderboard_recovery('bad')$$,'42501',null,'Anonymous clients have no recovery access');
select * from finish();rollback;
